$ErrorActionPreference='Stop'
[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
$runItem=Get-Item -LiteralPath 'C:\Users\22061\.codex\worktrees\96a3\FPGA_Competition\report\evidence\S2B-T06\ps_jtag_retry_20261009_165853_r02'
$captureItem=Get-Item -LiteralPath 'C:\Users\22061\.codex\worktrees\96a3\FPGA_Competition\report\evidence\S2B-T06\ps_smoke_hw_20261009_101728_r01\capture_uart.ps1'
if ((Get-FileHash -LiteralPath $captureItem.FullName -Algorithm SHA256).Hash.ToLowerInvariant() -cne '3b78f5b54dc7413821400e2c5df3bc1c73a93375b9b71ede9bec42a99e16605d') { throw '采集源码SHA改变' }
$knownPort=@(Get-CimInstance Win32_SerialPort | Where-Object { $_.DeviceID -ceq 'COM4' -and $_.PNPDeviceID -ceq 'USB\VID_10C4&PID_EA60\D02E61162787ED11A536569F9D1CC348' -and $_.Status -ceq 'OK' })
if ($knownPort.Count -ne 1) { throw 'COM4身份发生变化' }
$rawPath=Join-Path $runItem.FullName 'uart_raw.bin'
$stopPath=Join-Path $runItem.FullName 'stop_capture.flag'
$captureOut=Join-Path $runItem.FullName 'uart_capture_stdout.log'
$captureErr=Join-Path $runItem.FullName 'uart_capture_stderr.log'
$identityPath=Join-Path $runItem.FullName 'uart_capture_identity.json'
foreach ($candidate in @($rawPath,$stopPath,$captureOut,$captureErr,$identityPath)) { if (Test-Path -LiteralPath $candidate) { throw "拒绝覆盖：$candidate" } }
$existing=@(Get-CimInstance Win32_Process -Filter "Name='pwsh.exe'" | Where-Object { $_.ProcessId -ne $PID -and $_.CommandLine.Contains($captureItem.FullName) -and $_.CommandLine.Contains('-Port COM4') })
if ($existing.Count -ne 0) { throw '发现已有COM4采集者' }
$pwshItem=Get-Item -LiteralPath 'C:\Users\22061\.cache\codex-runtimes\codex-primary-runtime\dependencies\native\powershell\pwsh.exe'
$argText='-NoProfile -File "'+$captureItem.FullName+'" -Port COM4 -RawPath "'+$rawPath+'" -StopFlagPath "'+$stopPath+'"'
$ownedCapture=Start-Process -FilePath $pwshItem.FullName -ArgumentList $argText -WindowStyle Hidden -PassThru -RedirectStandardOutput $captureOut -RedirectStandardError $captureErr
$readyClock=[Diagnostics.Stopwatch]::StartNew()
$observedOut=''
$openedRecord=$null
do {
    if (Test-Path -LiteralPath $captureOut) {
        $stream=[IO.File]::Open($captureOut,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::ReadWrite)
        $reader=[IO.StreamReader]::new($stream,[Text.UTF8Encoding]::new($false,$true))
        try { $observedOut=$reader.ReadToEnd() } finally { $reader.Dispose() }
        if ($observedOut.Contains('CAPTURE_CLOSED ')) { throw '采集已关闭，禁止下载' }
        $openLines=@($observedOut.Split([char]10) | Where-Object { $_.StartsWith('CAPTURE_OPEN ') })
        if ($openLines.Count -eq 1) { $openedRecord=$openLines[0].Substring(13) | ConvertFrom-Json; break }
        if ($openLines.Count -gt 1) { throw '多个Open标记，拒绝使用' }
    }
    if ($ownedCapture.HasExited) { throw '采集提前退出' }
    Start-Sleep -Milliseconds 100
} while ($readyClock.Elapsed.TotalSeconds -lt 10)
if ($null -eq $openedRecord) { throw '10秒内没有真实串口Open标记' }
if ($openedRecord.port -cne 'COM4' -or $openedRecord.raw_path -cne $rawPath -or $openedRecord.stop_flag_path -cne $stopPath -or $openedRecord.baud -ne 115200 -or $openedRecord.format -cne '8N1' -or $openedRecord.flow_control -cne 'None' -or $openedRecord.dtr -ne $false -or $openedRecord.rts -ne $false) { throw '采集参数不符' }
$captureCim=Get-CimInstance Win32_Process -Filter "ProcessId=$($ownedCapture.Id)"
if ($null -eq $captureCim -or $captureCim.ExecutablePath -cne $pwshItem.FullName -or -not $captureCim.CommandLine.Contains($argText)) { throw '采集进程身份不符' }
$identity=[ordered]@{ status='CAPTURE_OPEN'; pid=$ownedCapture.Id; parent_pid=$captureCim.ParentProcessId; creation_time_filetime_utc=[string]$captureCim.CreationDate.ToFileTimeUtc(); executable_path=$captureCim.ExecutablePath; command_line=$captureCim.CommandLine; port='COM4'; port_pnp_id=$knownPort[0].PNPDeviceID; raw_path=$rawPath; stop_flag=$stopPath; observed_open=$openedRecord; parameters='115200/8N1/no-flow/DTR=false/RTS=false'; source_sha256='3b78f5b54dc7413821400e2c5df3bc1c73a93375b9b71ede9bec42a99e16605d'; ready_seconds=$readyClock.Elapsed.TotalSeconds; checked_at_utc8=[DateTimeOffset]::UtcNow.ToOffset([TimeSpan]::FromHours(8)).ToString('o') }
$identityText=$identity | ConvertTo-Json -Depth 8
$target=[IO.File]::Open($identityPath,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read)
try { $bytes=[Text.UTF8Encoding]::new($false).GetBytes($identityText+[Environment]::NewLine); $target.Write($bytes,0,$bytes.Length); $target.Flush() } finally { $target.Dispose() }
$identityText

